// Native video through the public workspace panel and Library, fictional generated bytes only.
// Run after building: node examples/workspace-app/journey-video.mjs
import assert from 'node:assert/strict';
import { mkdirSync, mkdtempSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { insecureUrl, launch, pause, q } from '@hachej/boring-testing/browser';

process.env.STUDIO_MODEL = 'scripted';
const { startWorkspaceApp } = await import('./server.mjs');
const evidence = '.cache/evidence/video';
mkdirSync(evidence, { recursive: true });
const app = await startWorkspaceApp({ directory: mkdtempSync(join(tmpdir(), 'boring-video-')), blobs: true });
const library = '[data-testid=workspace-library-side]';
const row = q(`${library} [role=treeitem][data-path="colour.mp4.blob.json"]`);
const video = q('[data-testid=viewer-panel] video');
let browser;
try {
  browser = await launch(insecureUrl(`${app.url}?blobs`), { evidence });
  await browser.until('the workspace', `!!${q('[data-testid=workspace-library]')}`, 20000);
  const open = async phone => {
    if (!(await browser.evaluate(`!!${q('[data-testid=workspace-library]')}?.checkVisibility()`))) {
      await browser.tap(q('[data-testid=sessions-toggle]'));
      await browser.until('the Library button', `!!${q('[data-testid=workspace-library]')}?.checkVisibility()`);
    }
    await (phone ? browser.tap : browser.click)(q('[data-testid=workspace-library]'));
    await browser.until('the video in the Library', `!!${row}`, 10000);
    await (phone ? browser.tap : browser.click)(`${row}.querySelector('button')`);
    await browser.until('native video from the pointer URL', `!!${video}`, 10000);
    assert.match(await browser.evaluate(`${video}.getAttribute('src')`), /^\/_files\/blob-/);
    assert.deepEqual(await browser.evaluate(`[${video}.controls, ${video}.playsInline, ${video}.preload, ${video}.autoplay]`), [true, true, 'metadata', false]);
    await browser.until('the generated video decodes', `${video}.readyState >= 2 && ${video}.videoWidth === 640`, 10000);
    await browser.send('Runtime.evaluate', { expression: `${video}.play()`, userGesture: true, awaitPromise: true });
    await browser.until('native playback advances', `${video}.currentTime > 0.2`, 10000);
    await browser.evaluate(`${video}.pause()`);
    await browser.click(q('[data-testid=viewer-more]'));
    await browser.until('the bar download', `!!${q('[data-testid=viewer-download]')}`);
    await browser.send('Input.dispatchKeyEvent', { type: 'keyDown', key: 'Escape', code: 'Escape' });
    await browser.send('Input.dispatchKeyEvent', { type: 'keyUp', key: 'Escape', code: 'Escape' });
  };
  const fits = async () => {
    assert.ok(await browser.evaluate(`document.documentElement.scrollWidth <= innerWidth && document.body.scrollWidth <= innerWidth`), 'no horizontal page overflow');
    assert.ok(await browser.evaluate(`(() => { const v = ${video}, p = ${q('[data-testid=viewer-body]')}; const r = v.getBoundingClientRect(), b = p.getBoundingClientRect(); return v.clientWidth > 0 && p.scrollWidth <= p.clientWidth && r.left >= b.left && r.right <= b.right + 1 && r.bottom <= b.bottom + 1; })()`), 'video fits the panel width and height');
  };
  for (const [name, width, height, phone] of [['desktop', 1440, 900, false], ['phone', 390, 844, true]]) {
    if (phone) {
      await browser.evaluate(`${q('[data-testid=viewer-close]')}?.click()`);
      await pause(300);
      await browser.emulate('phone');
    }
    await browser.send('Emulation.setDeviceMetricsOverride', { width, height, deviceScaleFactor: phone ? 2 : 1, mobile: phone });
    await open(phone);
    for (const scheme of ['light', 'dark']) {
      await browser.evaluate(`document.documentElement.classList.toggle('dark', ${scheme === 'dark'})`);
      await browser.send('Emulation.setEmulatedMedia', { features: [{ name: 'prefers-color-scheme', value: scheme }] });
      await pause(300);
      await fits();
      await browser.screenshot(`${name}-${width}-${scheme}.png`);
    }
    console.log(`ok  native video at ${width}, light and dark`);
  }
  await browser.send('Emulation.setDeviceMetricsOverride', { width: 360, height: 780, deviceScaleFactor: 2, mobile: true });
  await pause(300);
  await fits();
  await browser.evaluate(`${video}.dispatchEvent(new Event('error'))`);
  await browser.until('the codec fallback', `!!${q('[data-testid=video-unplayable]')}`);
  assert.equal(await browser.evaluate(`${q('[data-testid=video-unplayable]')}.textContent`), "This video can't be played here");
  assert.equal(await browser.evaluate(`!!${video}`), false, 'the broken box is gone');
  assert.equal(await browser.evaluate(`${q('[data-testid=video-download]')}.getAttribute('download')`), 'colour.mp4');
  assert.ok(await browser.evaluate('document.documentElement.scrollWidth <= innerWidth'), 'fallback has no overflow at 360');
  await browser.click(q('[data-testid=viewer-more]'));
  await browser.until('the bar still offers Download', `!!${q('[data-testid=viewer-download]')}`);
  console.log(`ok  360px has no overflow; error shows fallback and download\nScreenshots in ${evidence}`);
} finally {
  await browser?.close();
  await app.close();
}
